@Slf4j
@PluginDescriptor(name = "RuneWatch SA", description = "Shows players on the RuneWatch South America watchlist", tags = {
        "scam", "watch", "list", "south america", "sa", "runewatch" })
public class RuneWatchSAPlugin extends Plugin {
    @Inject
    private Client client;

    @Inject
    private RuneWatchSAConfig config;

    @Inject
    private CaseManager caseManager;

    @Inject
    private ChatMessageManager chatMessageManager;

    @Inject
    private ScheduledExecutorService executor;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private RuneWatchSAOverlay overlay;

    private RuneWatchSAPanel panel;
    private NavigationButton navButton;

    @Override
    protected void startUp() throws Exception {
        panel = injector.getInstance(RuneWatchSAPanel.class);

        // Link data loading to panel refresh
        caseManager.setOnDataLoaded(panel::refresh);

        // Fetch data once on startup
        executor.execute(caseManager::refresh);

        if (config.showSidebarIcon()) {
            setupNavButton();
        }

        overlayManager.add(overlay);
    }

    private void setupNavButton() {
        if (navButton != null)
            return;

        BufferedImage icon = null;
        try {
            icon = ImageUtil.loadImageResource(getClass(), "icon.png");
        } catch (Exception e) {
            log.error("Failed to load plugin icon", e);
        }

        if (icon != null) {
            navButton = NavigationButton.builder()
                    .tooltip("RuneWatch SA")
                    .icon(icon)
                    .priority(5)
                    .panel(panel)
                    .build();

            clientToolbar.addNavigation(navButton);
        }
    }

    private void removeNavButton() {
        if (navButton == null)
            return;

        NavigationButton button = navButton;
        navButton = null;

        // Remove na thread UI para evitar NPEs intermitentes
        SwingUtilities.invokeLater(() -> {
            try {
                clientToolbar.removeNavigation(button);
            } catch (Exception e) {
                log.warn("Failed to remove navigation button", e);
            }
        });
    }

    @Override
    protected void shutDown() throws Exception {
        removeNavButton();
        overlayManager.remove(overlay);
    }

    @Provides
    RuneWatchSAConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(RuneWatchSAConfig.class);
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!event.getGroup().equals("runewatchsa"))
            return;

        if (event.getKey().equals("showSidebarIcon")) {
            if (config.showSidebarIcon()) {
                setupNavButton();
            } else {
                removeNavButton();
            }
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged gameStateChanged) {
        if (gameStateChanged.getGameState() == GameState.LOGGING_IN) {
            executor.execute(caseManager::refresh);
        }
    }

    @Subscribe
    public void onPlayerSpawned(PlayerSpawned event) {
        if (!config.notifyOnRadius()) {
            return;
        }

        final Player player = event.getPlayer();
        if (player == null || player.getName() == null)
            return;

        final String name = Text.standardize(player.getName());
        Case c = caseManager.get(name);

        if (c != null) {
            final String message = new ChatMessageBuilder()
                    .append(Color.RED, "[RuneWatch SA] ")
                    .append(Color.ORANGE, "ALERTA: ")
                    .append(Color.WHITE, "O SCAMMER ")
                    .append(Color.RED, player.getName())
                    .append(Color.WHITE, " está próximo! Motivo: ")
                    .append(Color.YELLOW, c.getReason())
                    .build();

            chatMessageManager.queue(QueuedMessage.builder()
                    .type(ChatMessageType.GAMEMESSAGE)
                    .runeLiteFormattedMessage(message)
                    .build());
        }
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event) {
        if (event.getMenuOption().equals("Trade with") && config.notifyOnTrade()) {
            // O target vem como "<col=ffffff>Nome</col> (level-126)"
            String rawName = Text.removeTags(event.getMenuTarget());
            // Remove o "(level-126)"
            String cleanName = rawName.split(" \\(")[0].trim();
            final String name = Text.standardize(cleanName);

            final Case c = caseManager.get(name);

            if (c != null) {
                final String message = new ChatMessageBuilder()
                        .append(Color.RED, "[RuneWatch SA] ")
                        .append(Color.ORANGE, "PERIGO: ")
                        .append(Color.WHITE, "Você está negociando com o SCAMMER ")
                        .append(Color.RED, cleanName)
                        .append(Color.WHITE, ". Ele está na lista: ")
                        .append(Color.YELLOW, c.getReason())
                        .build();

                chatMessageManager.queue(QueuedMessage.builder()
                        .type(ChatMessageType.GAMEMESSAGE)
                        .runeLiteFormattedMessage(message)
                        .build());
            }
        }
    }

    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event) {
        if (!config.showInvestigateOption()) {
            return;
        }

        final String option = event.getOption();
        if (!option.equals("Trade with") && !option.equals("Walk here")) {
            return;
        }

        final Player player = event.getMenuEntry().getPlayer();
        if (player == null) {
            return;
        }

        final String name = Text.standardize(player.getName());
        final Case c = caseManager.get(name);

        if (c != null) {
            client.createMenuEntry(-1)
                    .setOption("Investigate")
                    .setTarget(event.getTarget())
                    .setType(MenuAction.RUNELITE)
                    .onClick(e -> LinkBrowser.browse(c.getEvidence()));
        }
    }
}

package com.runewatchsa;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.InputStreamReader;
import javax.swing.SwingUtilities;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;

import java.util.concurrent.TimeUnit;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Text;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

@Slf4j
@Singleton
public class CaseManager
{
    private static final String URL = "https://runewatch-sa.vercel.app/api/cases";

    private final OkHttpClient client;
    private final Gson gson;
    private final Map<String, Case> cases = new ConcurrentHashMap<>();
    private Runnable onDataLoaded = null;

    @Inject
    private CaseManager(OkHttpClient client, Gson gson)
    {
        // Aumentamos o timeout para 60s para lidar com o cold-start do Render
        this.client = client.newBuilder()
            .connectTimeout(60, TimeUnit.SECONDS)
            .readTimeout(60, TimeUnit.SECONDS)
            .writeTimeout(60, TimeUnit.SECONDS)
            .build();
        this.gson = gson;
    }

    public void setOnDataLoaded(Runnable callback)
    {
        this.onDataLoaded = callback;
    }

    public void refresh()
    {
        Request request = new Request.Builder()
            .url(URL)
            .build();

        client.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException e)
            {
                log.error("Error retrieving RuneWatch SA cases", e);
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException
            {
                if (response.isSuccessful())
                {
                    JsonArray array = gson.fromJson(new InputStreamReader(response.body().byteStream()), JsonArray.class);

                    cases.clear();
                    for (JsonElement element : array)
                    {
                        if (!element.isJsonObject()) continue;
                        JsonObject data = element.getAsJsonObject();
                        Case c = gson.fromJson(data, Case.class);

                        // Nome atual
                        String currentName = Text.standardize(c.getName());
                        cases.put(currentName, c);

                        // Histórico de nomes
                        if (data.has("nameHistory") && data.get("nameHistory").isJsonArray())
                        {
                            JsonArray history = data.getAsJsonArray("nameHistory");
                            for (JsonElement hElement : history)
                            {
                                String oldName = Text.standardize(hElement.getAsString());
                                if (!oldName.isEmpty() && !cases.containsKey(oldName))
                                {
                                    cases.put(oldName, c);
                                }
                            }
                        }
                    }

                    log.info("Loaded {} index entries for {} RuneWatch SA cases", cases.size(), array.size());

                    if (onDataLoaded != null)
                    {
                        SwingUtilities.invokeLater(onDataLoaded);
                    }
                }
                else
                {
                    log.error("Error retrieving RuneWatch SA cases: {}", response.code());
                }

                response.close();
            }
        });
    }

    public Case get(String name)
    {
        return cases.get(Text.standardize(name));
    }

    public List<Case> getCases()
    {
        return new ArrayList<>(new java.util.HashSet<>(cases.values()));
    }
}

package com.runewatchsa;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Keybind;

@ConfigGroup("runewatchsa")
public interface RuneWatchSAConfig extends Config {
    @ConfigItem(keyName = "notifyOnTrade", name = "Notificar ao negociar", description = "Notifica você quando negociar com um jogador da lista RuneWatch SA", position = 1)
    default boolean notifyOnTrade() {
        return true;
    }

    @ConfigItem(keyName = "notifyOnRadius", name = "Notificar por proximidade", description = "Notifica você quando um jogador da lista RuneWatch SA estiver por perto", position = 2)
    default boolean notifyOnRadius() {
        return true;
    }

    @ConfigItem(keyName = "showSidebarIcon", name = "Exibir Ícone Lateral", description = "Mostra ou esconde o ícone do RuneWatch SA no menu lateral do RuneLite", position = 3)
    default boolean showSidebarIcon() {
        return true;
    }

    @ConfigItem(keyName = "highlightScammers", name = "Sinalizar Scammers no Mundo", description = "Desenha marcações visuais em jogadores que estão na lista", position = 4)
    default boolean highlightScammers() {
        return true;
    }

    @ConfigItem(keyName = "drawPlayerName", name = "Mostrar Nome sobre o Scammer", description = "Exibe o nome do jogador em vermelho acima dele", position = 6)
    default boolean drawPlayerName() {
        return true;
    }

